// Lineage A, r1 E4: persistent batch-aligned rounds, fp32 h in TMEM, per-batch GRN counters, FP16x3 tcgen05.
// One cooperative launch. A round holds whole batches (bpr * HW <= 148 * 128 tokens); CTA c owns 128-token tile c of
// every round. Per round: x -> fp16 hi/lo (smem) -> GEMM1 swap-AB D1[hid][tok] = W1hi.Xhi + W1hi.Xlo + W1lo.Xhi in
// TMEM (512 cols) -> + b1, GELU, per-batch sumsq red.add -> per-batch counter -> s = 1 + gw G / (mean G + eps) ->
// h' = h s split hi/lo into MN-major smem -> GEMM2 swap-AB D2[c][tok] (main W2hi.h'hi, cross W2hi.h'lo + W2lo.h'hi in
// a separate accumulator, both in TMEM columns freed by h blocks 0/1) -> out = main + cross + b2 + W2.gb.
// Weights: phase 0 converts W1/W2 into fp16 hi/lo SW128 byte images (workspace), streamed by a 3 x 32 KB bulk ring.
#include <cuda_runtime.h>
#include <cuda_fp16.h>
#include <stdint.h>

struct EParams {
  const float* x; const float* w1; const float* b1; const float* gw; const float* gb; const float* w2; const float* b2;
  float* out; unsigned char* img; float* gsum; float* b2p;
  int B, HW, bpr, nrounds, tiles_last; float eps;
};

// [0] CTAs whose phase 0 (weight images, b2', gsum zeroing by CTA 0) is done, [1] departures, [16 + b] GEMM1 tiles
// published for batch b. The last departer resets them for the next call.
__device__ unsigned int g_ctr[16 + 64];

namespace {
constexpr int NTH = 576;            // warps 0..15 epilogue, 16 producer, 17 MMA
constexpr int OFF_R0 = 0;           // X hi | X lo (K-major SW128), later h' hi | lo of hidden blocks 0, 2 (MN-major SW128)
constexpr int OFF_R1 = 65536;       // h' hi | lo of hidden blocks 1, 3
constexpr int OFF_RING = 131072;    // 3 x 32 KB weight stages
constexpr int NSTAGE = 3;
constexpr uint32_t STAGE_BYTES = 32768;
constexpr int OFF_BAR = 229376;
constexpr int SMEM_TOTAL = OFF_BAR + 512 + 1024;
constexpr uint32_t ID1 = (1u << 4) | ((128u >> 3) << 17) | ((128u >> 4) << 24);  // f32 D, f16 A/B, both K-major, M=N=128
constexpr uint32_t ID2 = ID1 | (1u << 16);                                      // B MN-major

